def contains(others, o):
    # does any other object's bbox fully contain o's cells?
    for j,(c_,cells_) in enumerate(others):
        if j==others.index(o): continue
        rmin=min(a for a,b in cells_); rmax=max(a for a,b in cells_); cmin=min(b for a,b in cells_); cmax=max(b for a,b in cells_)
        if all(rmin<=a<=rmax and cmin<=b<=cmax for a,b in o[1]):
            return c_
    return None
