def f(I):
    Co=components(I); H,W=len(I),len(I[0])
    O=[r[:] for r in I]
    # identify the changed comp: color appearing in multiple comps where one is 'odd'? 
    # Instead: changed comp = the multi-cell comp whose color also appears in exactly one other comp with same shape? Simpler: use known pattern - find pairs of different-colored comps with identical normalized shape; the one INSIDE another comp's bbox gets recolored to that comp's color? But changed comps aren't inside bboxes of targets... except via their twin.
    # Rule candidate: for each pair of different-colored comps with equal nsh, if one comp's bbox is contained in the other comp's bbox, recolor the inner one to the outer comp's color.
    for A in Co:
        for B in Co:
            if A is B or A[0]==B[0]: continue
            if nsh(A[1])==nsh(B[1]):
                ba,bB=bb(A[1]),bb(B[1])
                # containment either way
                if (ba[0]>=bB[0] and ba[1]<=bB[1] and ba[2]>=bB[2] and ba[3]<=bB[3]):
                    for r,c in A[1]: O[r][c]=B[0]
                elif (bB[0]>=ba[0] and bB[1]<=ba[1] and bB[2]>=ba[2] and bB[3]<=ba[3]):
                    for r,c in B[1]: O[r][c]=A[0]
    return O
